import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let xs = [1, 2, 3]
    let sum = 0
    for x in xs { sum = sum + x }
    if sum == 6 { io.println("sum-ok") } else { io.println("sum-bad") }

    let c = 0
    for x in xs { c = c + 1 }
    if c == 3 { io.println("again-ok") } else { io.println("again-bad") }

    let b = 0
    for x in xs {
        if x == 2 { break }
        b = b + 1
    }
    if b == 1 { io.println("break-ok") } else { io.println("break-bad") }

    let k = 0
    for x in xs {
        if x == 2 { continue }
        k = k + 1
    }
    if k == 2 { io.println("cont-ok") } else { io.println("cont-bad") }

    let d = 0
    for x in [4, 5] { d = d + x }
    if d == 9 { io.println("direct-ok") } else { io.println("direct-bad") }

    let n = 0
    for _ in xs { n = n + 1 }
    if n == 3 { io.println("blank-ok") } else { io.println("blank-bad") }

    let e = 0
    for x in xs {
        for y in xs { e = e + 1 }
    }
    if e == 9 { io.println("nested-ok") } else { io.println("nested-bad") }

    return Ok(())
}
